package com.frostsecurity.extreme.storage;
import com.frostsecurity.extreme.core.SecurityFinding; import com.google.gson.*; import java.nio.file.*; import java.io.*; import java.util.*;
public final class FrostStorage { private static Path dir; public static void init(){dir=Paths.get(System.getProperty("user.dir"),"frostscan-data");try{Files.createDirectories(dir);}catch(IOException ignored){}} public static void appendFinding(SecurityFinding f){try{Path p=dir.resolve("findings.jsonl");JsonObject o=new JsonObject();o.addProperty("id",f.id());o.addProperty("severity",f.severity().name());o.addProperty("confidence",f.confidence());o.addProperty("title",f.title());o.addProperty("explanation",f.explanation());o.addProperty("createdAt",f.createdAt().toString());Files.writeString(p,new Gson().toJson(o)+System.lineSeparator(),StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(Exception ignored){}} public static Path directory(){return dir;} }
